```

`core` defines the boundary:

```go
// core/provider.go
package core

import "context"

type SandboxOptions struct {
	Name     string
	Image    string
	Env      map[string]string
	Region   string
	Labels   map[string]string
	CPU      float64
	MemoryMB int
}

type Provider interface {
	CreateSandbox(ctx context.Context, opts SandboxOptions) (any, error)
	GetSandbox(ctx context.Context, id string) (any, error)
	DeleteSandbox(ctx context.Context, id string) error
}

type Client struct {
	provider Provider
}

func NewClient(provider Provider) *Client {
	return &Client{provider: provider}
}

func (c *Client) CreateSandbox(
	ctx context.Context,
	opts SandboxOptions,
) (any, error) {
	return c.provider.CreateSandbox(ctx, opts)
}
```

The Modal adapter owns Modal configuration and mapping:

```go
// adapters/modal/adapter.go
package modal

import (
	"context"

	"github.com/sandbox-kit/kit/core"
	modal "github.com/modal-labs/modal-client/go"
)

type Config struct {
	TokenID    string
	TokenSecret string
}

type Adapter struct {
	client *modal.Client
}

func New(cfg Config) (*Adapter, error) {
	client, err := modal.NewClient(
		// Illustrative: use the actual Modal SDK constructor/config.
		modal.WithToken(cfg.TokenID, cfg.TokenSecret),
	)
	if err != nil {
		return nil, err
	}

	return &Adapter{client: client}, nil
}

func (a *Adapter) CreateSandbox(
	ctx context.Context,
	opts core.SandboxOptions,
) (any, error) {
	app, err := a.client.Apps.FromName(ctx, opts.Name, nil)
	if err != nil {
		return nil, err
	}

	image := a.client.Images.FromRegistry(opts.Image, nil)

	return a.client.Sandboxes.Create(ctx, app, image, &modal.SandboxCreateParams{
		// Map only fields Modal supports.
		Region: opts.Region,
	})
}

func (a *Adapter) GetSandbox(
	ctx context.Context,
	id string,
) (any, error) {
	return a.client.Sandboxes.FromID(ctx, id, nil)
}

func (a *Adapter) DeleteSandbox(
	ctx context.Context,
	id string,
) error {
	sandbox, err := a.client.Sandboxes.FromID(ctx, id, nil)
	if err != nil {
		return err
	}

	_, err = sandbox.Terminate(ctx, nil)
	return err
}
```

The Daytona adapter has its own client and mappings:

```go
// adapters/daytona/adapter.go
package daytona

import (
	"context"

	"github.com/sandbox-kit/kit/core"
	daytona "github.com/daytonaio/daytona/libs/sdk-go/pkg/daytona"
	"github.com/daytonaio/daytona/libs/sdk-go/pkg/types"
)

type Config struct {
	APIKey  string
	BaseURL string
}

type Adapter struct {
	client *daytona.Client
}

func New(cfg Config) (*Adapter, error) {
	client, err := daytona.NewClientWithConfig(&types.DaytonaConfig{
		APIKey:  cfg.APIKey,
		BaseURL: cfg.BaseURL,
	})
	if err != nil {
		return nil, err
	}

	return &Adapter{client: client}, nil
}

func (a *Adapter) CreateSandbox(
	ctx context.Context,
	opts core.SandboxOptions,
) (any, error) {
	// Map only fields that Daytona actually supports.
	return a.client.Create(ctx, &types.CreateSandboxParams{
		Name:  opts.Name,
		Image: opts.Image,
		Env:   opts.Env,
	})
}

func (a *Adapter) GetSandbox(
	ctx context.Context,
	id string,
) (any, error) {
	return a.client.Get(ctx, id)
}

func (a *Adapter) DeleteSandbox(
	ctx context.Context,
	id string,
) error {
	return a.client.Delete(ctx, id)
}
```

User code selects one adapter:

```go
package main

import (
	"context"
	"log"

	"github.com/sandbox-kit/kit/core"
	"github.com/sandbox-kit/kit/adapters/modal"
)

func main() {
	ctx := context.Background()

	provider, err := modal.New(modal.Config{
		TokenID:     "xxx",
		TokenSecret: "yyy",
	})
	if err != nil {
		log.Fatal(err)
	}

	client := core.NewClient(provider)

	sandbox, err := client.CreateSandbox(ctx, core.SandboxOptions{
		Name:  "agent-sandbox",
		Image: "alpine:3.21",
		Env: map[string]string{
			"MODE": "development",
		},
	})
	if err != nil {
		log.Fatal(err)
	}

	log.Printf("%#v", sandbox)
}
```

The important part is that `core` does not import Modal or Daytona. Each adapter maps the shared request into the provider’s API and returns the provider’s native result and error.

The exact Modal and Daytona method names above should be treated as architectural examples; when implementing, we should verify them against their current Go SDKs.

[116] assistant: You do not need gRPC for the first version.

Use:

- **Protobuf** for shared schemas, enums, capability definitions, and generated data types.
- **gRPC** only if you later need a network service between processes or a remote `sandbox-kit` control plane.

Since your adapters communicate directly with Modal and Daytona, there is no internal service that requires gRPC. Adding gRPC now would introduce generated service clients, transport behavior, and another contract layer you do not currently need.

For language-specific naming, protobuf supports package and code-generation options:

```proto
syntax = "proto3";

package sandboxkit.v1;

option go_package = "github.com/sandbox-kit/kit/gen/go/sandboxkit/v1;sandboxkitv1";
option java_package = "io.sandboxkit.v1";
option csharp_namespace = "SandboxKit.V1";

message Sandbox {
  string sandbox_id = 1;
  string created_at = 2;
}
```

Generators translate protobuf naming into language conventions:

- `sandbox_id` may become `SandboxId` in Go or `sandboxId` in JavaScript, depending on the generator.
- `CreateSandbox` may generate `CreateSandbox` in Go and `createSandbox` in JavaScript.
- Package and namespace options control where generated code lives.

But `NewClient()` versus `new Client()` is not something protobuf should define. That is the user-facing SDK design. Keep generated protobuf code underneath your SDK and write thin, idiomatic wrappers:

```go
client := modal.NewClient(config)
```

```ts
const client = new ModalClient(config)
```

The protobuf contracts should define stable concepts and wire names. Each language SDK should expose native conventions on top of those generated types. This also lets you preserve provider-native responses and errors instead of forcing every language through a generated universal client API.

