// This example initializes one provider adapter. It does not create sandboxes.
package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"time"

	sandbox "github.com/sandbox-kit/kit"
	"github.com/sandbox-kit/kit/adapters/daytona"
	"github.com/sandbox-kit/kit/adapters/modal"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Println("Usage: go run . modal|daytona (uses the selected SDK's native credential configuration)")
		return
	}
	var err error
	switch os.Args[1] {
	case "modal":
		err = runModal()
	case "daytona":
		err = runDaytona()
	default:
		err = fmt.Errorf("unknown provider %q", os.Args[1])
	}
	if err != nil {
		log.Fatal(err)
	}
}

func runModal() error {
	adapter, err := modal.NewAdapter(nil)
	if err != nil {
		return err
	}
	defer adapter.SDK().Close()
	client, err := sandbox.NewClient(adapter)
	if err != nil {
		return err
	}
	fmt.Printf("%s adapter initialized (SDK %s); credentials have not been verified with the provider\n",
		client.Sandbox().SandboxProvider(), client.Sandbox().SDK().Version())
	return nil
}

func runDaytona() (err error) {
	adapter, err := daytona.NewAdapter(nil)
	if err != nil {
		return err
	}
	defer func() {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if closeErr := adapter.SDK().Close(ctx); closeErr != nil {
			if err == nil {
				err = closeErr
			} else {
				log.Printf("Daytona cleanup: %v", closeErr)
			}
		}
	}()
	client, err := sandbox.NewClient(adapter)
	if err != nil {
		return err
	}
	fmt.Printf("%s adapter initialized; credentials have not been verified with the provider\n",
		client.Sandbox().SandboxProvider())
	return nil
}
"}

